def empty_catalog_entry(group: str, item_id: str) -> dict[str, object]:
    label = {"es": "", "ca": "", "en": ""}
    if group == "trophic_modes":
        return {"id": item_id, "label": label, "description": ""}
    if group == "host_taxa":
        return {
            "id": item_id,
            "rank": "",
            "scientific_name": "",
            "genus": None,
            "family": "",
            "common_names": {"es": [], "ca": [], "en": []},
            "parent_id": None,
            "gis_aliases": [],
        }
    if group == "forest_types":
        return {"id": item_id, "label": label, "dominant_host_ids": [], "gis_aliases": []}
    if group == "soil_types":
        return {"id": item_id, "label": label, "ph_min": None, "ph_max": None, "gis_aliases": []}
    if group == "lithology_types":
        return {
            "id": item_id,
            "label": label,
            "general_reaction": "",
            "parent_soil_tendency_ids": [],
            "gis_aliases": [],
        }
    if group == "aspects":
        return {"id": item_id, "label": label, "azimuth_min": None, "azimuth_max": None}
    if group == "season_patterns":
        return {"id": item_id, "label": label}
    if group == "habitat_features":
        return {"id": item_id, "label": label}
    if group == "observation_flush_abundance":
        return {"id": item_id, "label": label, "prediction_favorable": 0, "calibration_score": None}
    return {"id": item_id, "label": label}


def validate_new_catalog_entry_id(group: str, item_id: str) -> tuple[bool, str]:
    if group not in CATALOG_ID_PREFIXES:
        return False, f"Catalog group {group or '-'} is not editable."
    if not re.fullmatch(r"[a-z][a-z0-9_]*", item_id):
        return False, "ID must use lowercase letters, numbers and underscores, starting with a letter."
    expected_prefix = CATALOG_ID_PREFIXES[group]
    if not item_id.startswith(expected_prefix):
        return False, f"ID for {group} must start with {expected_prefix}."
    return True, ""


def replace_catalog_entry(catalog_payload: dict[str, object], group: str, item_id: str, entry: dict[str, object]) -> tuple[bool, str]:
    if str(entry.get("id", "")) != item_id:
        return False, "Entry ID cannot be changed in the first maintenance UI."
    catalogs = catalog_payload.get("catalogs")
    if not isinstance(catalogs, dict):
        return False, "Catalog payload does not contain a catalogs object."
    items = catalogs.get(group)
    if not isinstance(items, list):
        return False, f"Catalog group {group} was not found."
    for index, existing in enumerate(items):
        if isinstance(existing, dict) and str(existing.get("id", "")) == item_id:
            items[index] = entry
            return True, f"Updated catalog entry {item_id}."
    return False, f"Catalog entry {item_id} was not found."


def catalog_split_list(value: str) -> list[str]:
    normalized = value.replace(",", "\n")
    return [part.strip() for part in normalized.splitlines() if part.strip()]


def catalog_form_string(form: dict[str, list[str]], name: str) -> str:
    values = form.get(name, [])
    return values[0].strip() if values else ""


def catalog_form_list(form: dict[str, list[str]], name: str) -> list[str]:
    """Return a cleaned list from a repeated form field."""
    return [value.strip() for value in form.get(name, []) if value.strip()]


def catalog_form_nullable_string(form: dict[str, list[str]], name: str) -> str | None:
    value = catalog_form_string(form, name)
    return value or None


def catalog_form_optional_number(form: dict[str, list[str]], name: str) -> float | int | None:
    value = catalog_form_string(form, name).replace(",", ".")
    if not value:
        return None
    number = float(value)
    return int(number) if number.is_integer() else number


def normalize_known_site_id(value: object) -> str:
    text = unicodedata.normalize("NFKD", str(value or "")).encode("ascii", "ignore").decode("ascii")
    text = re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_")
    if not text or not text[0].isalpha():
        raise ValueError("Name must contain at least one letter to generate an ID.")
    return text


def known_site_geometry_from_form(form: dict[str, list[str]]) -> dict[str, object] | None:
    value = catalog_form_string(form, "geometry_json")
    if not value:
        return None
    payload = json.loads(value)
    if not isinstance(payload, dict):
        raise ValueError("Geometry must be a GeoJSON object.")
    return payload


def known_site_location_from_form(form: dict[str, list[str]]) -> dict[str, float] | None:
    lat = catalog_form_optional_number(form, "lat")
    lon = catalog_form_optional_number(form, "lon")
    if lat is None and lon is None:
        return None
    if lat is None or lon is None:
        raise ValueError("Representative latitude and longitude must be provided together.")
    return {"lat": float(lat), "lon": float(lon)}


def known_site_area_from_form(form: dict[str, list[str]], existing: dict[str, object] | None = None) -> dict[str, object]:
    area_id = catalog_form_string(form, "area_id")
    row = dict(existing or mushroom_known_sites.empty_area(area_id))
    geometry = known_site_geometry_from_form(form)
    representative_location = known_site_location_from_form(form)
    derived_context = dict(existing.get("derived_context", {})) if isinstance(existing, dict) and isinstance(existing.get("derived_context"), dict) else {}
    derived_context.update(mushroom_known_sites.derive_geometry_context(geometry))
    gis_report_json = catalog_form_string(form, "gis_report_json")
    if gis_report_json:
        derived_context["gis_dem"] = json.loads(gis_report_json)
    if representative_location is None and isinstance(derived_context.get("geometry"), dict):
        representative_location = derived_context["geometry"].get("centroid")
    row.update(
        {
            "area_id": area_id,
            "name": catalog_form_string(form, "name"),
            "description": catalog_form_string(form, "description"),
            "aliases": catalog_split_list(catalog_form_string(form, "aliases")),
            "administrative_location": {
                "municipality": catalog_form_string(form, "municipality"),
                "county": catalog_form_string(form, "county"),
                "province": catalog_form_string(form, "province"),
                "country": catalog_form_string(form, "country"),
            },
            "representative_location": representative_location,
            "geometry": geometry,
            "derived_context": derived_context,
            "notes": catalog_form_string(form, "notes"),
        }
    )
    metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
    metadata["updated_at"] = datetime.now(UTC).date().isoformat()
    row["metadata"] = metadata
    return row


def known_site_micro_area_from_form(form: dict[str, list[str]], existing: dict[str, object] | None = None) -> dict[str, object]:
    micro_id = catalog_form_string(form, "micro_area_id")
    row = dict(existing or mushroom_known_sites.empty_micro_area(micro_id, catalog_form_string(form, "area_id")))
    geometry = known_site_geometry_from_form(form)
    representative_location = known_site_location_from_form(form)
    derived_context = dict(existing.get("derived_context", {})) if isinstance(existing, dict) and isinstance(existing.get("derived_context"), dict) else {}
    derived_context.update(mushroom_known_sites.derive_geometry_context(geometry))
    gis_report_json = catalog_form_string(form, "gis_report_json")
    if gis_report_json:
        derived_context["gis_dem"] = json.loads(gis_report_json)
    if representative_location is None and isinstance(derived_context.get("geometry"), dict):
        representative_location = derived_context["geometry"].get("centroid")
    row.update(
        {
            "micro_area_id": micro_id,
            "area_id": catalog_form_string(form, "area_id"),
            "name": catalog_form_string(form, "name"),
            "description": catalog_form_string(form, "description"),
            "aliases": catalog_split_list(catalog_form_string(form, "aliases")),
            "representative_location": representative_location,
            "geometry": geometry,
            "derived_context": derived_context,
            "location_precision_m": catalog_form_optional_number(form, "location_precision_m"),
            "altitude": {
                "min_m": catalog_form_optional_number(form, "altitude_min_m"),
                "max_m": catalog_form_optional_number(form, "altitude_max_m"),
                "source": catalog_form_string(form, "altitude_source"),
            },
            "topography": {
                "aspect_ids": catalog_split_list(catalog_form_string(form, "aspect_ids")),
                "slope_notes": catalog_form_string(form, "slope_notes"),
                "exposure_notes": catalog_form_string(form, "exposure_notes"),
            },
            "ecology": {
                "host_ids": catalog_split_list(catalog_form_string(form, "host_ids")),
                "forest_type_ids": catalog_split_list(catalog_form_string(form, "forest_type_ids")),
                "soil_tendency_ids": catalog_split_list(catalog_form_string(form, "soil_tendency_ids")),
                "habitat_feature_ids": catalog_split_list(catalog_form_string(form, "habitat_feature_ids")),
                "notes": catalog_form_string(form, "ecology_notes"),
            },
            "access": {
                "difficulty": catalog_form_string(form, "access_difficulty"),
                "notes": catalog_form_string(form, "access_notes"),
            },
            "provenance": {
                "source": catalog_form_string(form, "provenance_source") or "manual",
                "confidence": catalog_form_string(form, "provenance_confidence"),
                "notes": catalog_form_string(form, "provenance_notes"),
            },
            "notes": catalog_form_string(form, "notes"),
        }
    )
    metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
    metadata["updated_at"] = datetime.now(UTC).date().isoformat()
    row["metadata"] = metadata
    return row


def refresh_micro_area_dem_altitude(
    row: dict[str, object],
    existing: dict[str, object] | None = None,
    supplied_report: dict[str, object] | None = None,
) -> bool:
    """Refresh cached DEM altitude only for new or changed micro-area geometry."""
    geometry = row.get("geometry")
    previous_geometry = existing.get("geometry") if isinstance(existing, dict) else None
    geometry_changed = existing is None or geometry != previous_geometry
    previous_context = existing.get("derived_context") if isinstance(existing, dict) else None
    previous_report = (
        previous_context.get("gis_dem")
        if isinstance(previous_context, dict)
        and isinstance(previous_context.get("gis_dem"), dict)
        else None
    )
    cached_report = supplied_report or previous_report
    if not geometry:
        if geometry_changed:
            context = row.get("derived_context")
            if isinstance(context, dict):
                context.pop("gis_dem", None)
            altitude = row.get("altitude")
            previous_altitude = existing.get("altitude") if isinstance(existing, dict) else None
            automatic_source = str(
                (altitude.get("source") if isinstance(altitude, dict) else "")
                or (previous_altitude.get("source") if isinstance(previous_altitude, dict) else "")
                or ""
            ).startswith("dem_")
            if automatic_source:
                row["altitude"] = {
                    "min_m": None,
                    "max_m": None,
                    "mean_m": None,
                    "source": "",
                }
        return False
    if not geometry_changed and isinstance(cached_report, dict):
        mushroom_gis_lab.apply_micro_area_dem_altitude_report(row, cached_report)
        return False
    if geometry_changed and isinstance(supplied_report, dict) and supplied_report.get("dem_status") == "ok":
        mushroom_gis_lab.apply_micro_area_dem_altitude_report(row, supplied_report)
        return False
    mushroom_gis_lab.materialize_micro_area_dem_altitude(row)
    return True


def refresh_micro_area_soilgrids_context(
    row: dict[str, object],
    existing: dict[str, object] | None = None,
    *,
    cache_root: Path | None = None,
    ensure_missing: bool = True,
) -> bool:
    """Reuse or refresh static SoilGrids context after a geometry change."""
    geometry = row.get("geometry")
    previous_geometry = existing.get("geometry") if isinstance(existing, dict) else None
    geometry_changed = existing is None or geometry != previous_geometry
    derived_context = row.get("derived_context")
    if not isinstance(derived_context, dict):
        derived_context = {}
        row["derived_context"] = derived_context
    previous_contexts = existing.get("derived_context") if isinstance(existing, dict) else None
    previous_soilgrids = (
        previous_contexts.get("soilgrids_water")
        if isinstance(previous_contexts, dict)
        else None
    )
    if not geometry:
        if geometry_changed:
            derived_context.pop("soilgrids_water", None)
        return False
    if not geometry_changed and mushroom_soilgrids.context_is_current(
        previous_soilgrids, geometry
    ):
        mushroom_soilgrids.apply_micro_area_context(row, previous_soilgrids)
        return False
    context = mushroom_soilgrids.resolve_geometry_context(
        cache_root or mushroom_soilgrids.default_cache_root(),
        geometry,
        ensure_missing=ensure_missing,
    )
    mushroom_soilgrids.apply_micro_area_context(row, context)
    return True


def catalog_form_labels(form: dict[str, list[str]]) -> dict[str, str]:
    return {language: catalog_form_string(form, f"label_{language}") for language in ("es", "ca", "en")}


def catalog_entry_from_form(group: str, item_id: str, existing: dict[str, object], form: dict[str, list[str]]) -> dict[str, object]:
    entry = dict(existing)
    entry["id"] = item_id
    if group == "host_taxa":
        entry["rank"] = catalog_form_string(form, "rank")
        entry["scientific_name"] = catalog_form_string(form, "scientific_name")
        entry["genus"] = catalog_form_nullable_string(form, "genus")
        entry["family"] = catalog_form_string(form, "family")
        entry["parent_id"] = catalog_form_nullable_string(form, "parent_id")
        entry["common_names"] = {
            "es": catalog_split_list(catalog_form_string(form, "common_names_es")),
            "ca": catalog_split_list(catalog_form_string(form, "common_names_ca")),
            "en": catalog_split_list(catalog_form_string(form, "common_names_en")),
        }
        entry["gis_aliases"] = catalog_split_list(catalog_form_string(form, "gis_aliases"))
        return entry

    entry["label"] = catalog_form_labels(form)
    if group == "forest_types":
        entry["parent_id"] = catalog_form_nullable_string(form, "parent_id")
        entry["dominant_host_ids"] = catalog_split_list(catalog_form_string(form, "dominant_host_ids"))
        entry["soil_bias_ids"] = catalog_split_list(catalog_form_string(form, "soil_bias_ids"))
        entry["gis_aliases"] = catalog_split_list(catalog_form_string(form, "gis_aliases"))
    elif group == "soil_types":
        entry["ph_min"] = catalog_form_optional_number(form, "ph_min")
        entry["ph_max"] = catalog_form_optional_number(form, "ph_max")
        for field in ("texture", "organic_matter", "drainage"):
            value = catalog_form_string(form, field)
            if value or field in entry:
                entry[field] = value
        entry["gis_aliases"] = catalog_split_list(catalog_form_string(form, "gis_aliases"))
    elif group == "lithology_types":
        entry["general_reaction"] = catalog_form_string(form, "general_reaction")
        entry["parent_soil_tendency_ids"] = catalog_split_list(catalog_form_string(form, "parent_soil_tendency_ids"))
        entry["gis_aliases"] = catalog_split_list(catalog_form_string(form, "gis_aliases"))
    elif group == "aspects":
        entry["azimuth_min"] = catalog_form_optional_number(form, "azimuth_min")
        entry["azimuth_max"] = catalog_form_optional_number(form, "azimuth_max")
    elif group == "observation_flush_abundance":
        favorable = catalog_form_string(form, "prediction_favorable")
        if favorable not in {"0", "1"}:
            raise ValueError("prediction_favorable must be 0 or 1")
        entry["prediction_favorable"] = int(favorable)
        entry["calibration_score"] = catalog_form_optional_number(form, "calibration_score")
    if "description" in entry or group == "trophic_modes":
        entry["description"] = catalog_form_string(form, "description")
    if "notes" in entry:
        entry["notes"] = catalog_form_string(form, "notes")
    return entry


def update_catalog_entry_from_form(catalog_payload: dict[str, object], group: str, item_id: str, form: dict[str, list[str]]) -> tuple[bool, str]:
    catalogs = catalog_payload.get("catalogs")
    if not isinstance(catalogs, dict):
        return False, "Catalog payload does not contain a catalogs object."
    items = catalogs.get(group)
    if not isinstance(items, list):
        return False, f"Catalog group {group} was not found."
    for index, existing in enumerate(items):
        if isinstance(existing, dict) and str(existing.get("id", "")) == item_id:
            items[index] = catalog_entry_from_form(group, item_id, existing, form)
            return True, f"Updated catalog entry {item_id}."
    return False, f"Catalog entry {item_id} was not found."


def gis_mapping_from_form(form: dict[str, list[str]]) -> tuple[dict[str, object] | None, str]:
    source_id = catalog_form_string(form, "source_id")
    field = catalog_form_string(form, "field")
    raw_value = catalog_form_string(form, "raw_value")
    if not source_id or not field or not raw_value:
        return None, "Source, field and raw value are required."
    confidence = catalog_form_string(form, "confidence") or "medium"
    review_status = catalog_form_string(form, "review_status") or "pending_review"
    mapping: dict[str, object] = {
        "source_id": source_id,
        "field": field,
        "raw_value": raw_value,
        "confidence": confidence,
        "review_status": review_status,
    }
    mapped_count = 0
    for target_field, _catalog_group in mushroom_gis_mappings_ui.TARGET_CATALOG_FIELDS:
        values = [str(value).strip() for value in form.get(target_field, []) if str(value).strip()]
        if values:
            mapping[target_field] = values
            mapped_count += len(values)
    notes = catalog_form_string(form, "notes")
    if notes:
        mapping["notes"] = notes
    if review_status == "accepted" and mapped_count == 0:
        return None, "Accepted GIS mappings must select at least one catalog target. Use ignored if this raw value should not map to the model."
    return mapping, "ok"


def upsert_exact_gis_mapping(gis_payload: dict[str, object], mapping: dict[str, object]) -> tuple[bool, str]:
    mappings = gis_payload.setdefault("exact_value_mappings", [])
    if not isinstance(mappings, list):
        return False, "GIS payload exact_value_mappings must be a list."
    key = mushroom_gis_mappings_ui.mapping_key(
        mapping.get("source_id", ""),
        mapping.get("field", ""),
        mapping.get("raw_value", ""),
    )
    for index, existing in enumerate(mappings):
        if not isinstance(existing, dict):
            continue
        existing_key = mushroom_gis_mappings_ui.mapping_key(
            existing.get("source_id", ""),
            existing.get("field", ""),
            existing.get("raw_value", ""),
        )
        if existing_key == key:
            mappings[index] = mapping
            return True, f"Updated GIS mapping for {mapping.get('source_id')}.{mapping.get('field')}."
    mappings.append(mapping)
    return True, f"Created GIS mapping for {mapping.get('source_id')}.{mapping.get('field')}."


