def complete_mushroom_ml_multiversion_result(
    payload: object,
    *,
    auth_token: str,
) -> tuple[int, dict[str, object]]:
    if not isinstance(payload, dict):
        return 400, {"ok": False, "error": "Worker result payload must be an object."}
    worker_id = str(payload.get("worker_id", ""))
    job_id = str(payload.get("job_id", ""))
    claim_token = str(payload.get("claim_token", ""))
    if not authenticate_mushroom_worker(worker_id, auth_token):
        return 401, {"ok": False, "error": "Worker authentication failed."}
    try:
        with RUN_LOCK:
            job = mushroom_worker_jobs.authorize_ml_multiversion_result_upload(
                mushroom_worker_jobs_path(),
                job_id=job_id,
                worker_id=worker_id,
                claim_token=claim_token,
            )
        job_purpose = str(job.get("job_purpose") or "benchmark")
        verification = mushroom_ml_multiversion_transport.finalize_result(
            mushroom_worker_candidate_results_path(),
            job_id=job_id,
            registry_path=mushroom_paths.mushroom_ml_version_registry_path(),
            models_root=mushroom_paths.mushroom_ml_models_dir(),
            job_purpose=job_purpose,
        )
        if job_purpose == "operational":
            input_bundle = job.get("input_bundle")
            input_bundle = input_bundle if isinstance(input_bundle, dict) else {}
            multiversion_spec = input_bundle.get("multiversion_spec")
            multiversion_spec = (
                multiversion_spec if isinstance(multiversion_spec, dict) else {}
            )
            if (
                verification.get("operational_scope_id")
                != multiversion_spec.get("operational_scope_id")
                or verification.get("operational_plan_id")
                != multiversion_spec.get("operational_plan_id")
            ):
                raise ValueError(
                    "Verified operational result does not match its queued scope and plan"
                )
    except (FileExistsError, FileNotFoundError, KeyError, ValueError, json.JSONDecodeError) as exc:
        return 409, {"ok": False, "error": str(exc)}
    return 200, {"ok": True, "verification": verification}


def _run_mushroom_full_update_promotion(
    rebuild_job_id: str,
    training_job_id: str,
    operational_job_id: str,
) -> None:
    """Publish one verified reconstruction and its linked trained models."""
    models_root = mushroom_paths.mushroom_ml_models_dir()
    registry_path = mushroom_paths.mushroom_ml_version_registry_path()
    previous_registry = registry_path.read_bytes()
    revisions_path = models_root / "current-input-revisions.json"
    previous_revisions = revisions_path.read_bytes() if revisions_path.is_file() else None
    installed_batch_id = ""
    generation_promoted = False
    try:
        with MUSHROOM_WORKER_PROMOTION_LOCK:
            def report_progress(percent: int, phase: str, message: str) -> None:
                with RUN_LOCK:
                    mushroom_worker_jobs.update_candidate_promotion_progress(
                        mushroom_worker_jobs_path(),
                        job_id=training_job_id,
                        percent=percent,
                        phase=phase,
                        message=message,
                    )

            report_progress(3, "Promoting full generation", "Installing the verified active-generation models.")
            operational_install = (
                mushroom_ml_multiversion_transport.install_staged_operational_result(
                    mushroom_worker_candidate_results_path(),
                    job_id=operational_job_id,
                    registry_path=mushroom_paths.mushroom_ml_version_registry_path(),
                    models_root=models_root,
                )
            )
            installed_batch_id = str(operational_install["batch_id"])
            installed_manifest = json.loads(
                (
                    models_root
                    / "batches"
                    / installed_batch_id
                    / "manifest.json"
                ).read_text(encoding="utf-8")
            )
            installed_registry = mushroom_ml_version_registry.install_batch_generations(
                mushroom_ml_version_registry.load_registry(registry_path),
                installed_manifest,
                approved_by="linked_full_update",
            )
            mushroom_ml_version_registry.save_registry(
                registry_path, installed_registry
            )
            mushroom_ml_training_freshness.publish_current_revisions(
                revisions_path,
                installed_manifest["input_revisions"],
            )
            report_progress(10, "Promoting full generation", "Publishing verified reconstructed artifacts.")
            rebuild_promotion = mushroom_worker_results.promote_verified_candidate(
                mushroom_worker_candidate_results_path(),
                mushroom_worker_input_bundles_path(),
                mushroom_paths.mushroom_rebuild_artifacts_dir(),
                job_id=rebuild_job_id,
                observations_path=mushroom_paths.mushroom_observations_path(),
                reference_catalogs_path=mushroom_paths.mushroom_reference_catalogs_path(),
                gis_mappings_path=mushroom_paths.mushroom_data_file("mushroom_gis_mappings.json"),
                weather_data_dir=mushroom_paths.weather_data_dir(),
                gis_root=mushroom_gis_lab.gis_root(),
                progress_callback=lambda percent, phase, message: report_progress(
                    min(70, 5 + int(percent * 0.65)), phase, message
                ),
            )
            report_progress(72, "Promoting full generation", "Publishing models trained from the same candidate.")
            try:
                training_promotion = mushroom_worker_results.promote_ml_train_candidate(
                    mushroom_worker_candidate_results_path(),
                    models_root,
                    job_id=training_job_id,
                    report_path=mushroom_paths.mushroom_ml_report_json_path(),
                )
            except BaseException:
                mushroom_worker_results.rollback_promoted_candidate(
                    mushroom_worker_candidate_results_path(),
                    mushroom_paths.mushroom_rebuild_artifacts_dir(),
                    job_id=rebuild_job_id,
                )
                raise
            released = mushroom_predictor_ui.release_predictor_cache()
            runtime_publication = refresh_mushroom_predictor_runtime_publication()
            mushroom_model_state.clear_all_pending(full_rebuild=True)
            generation_promoted = True
            report_progress(99, "Full generation promoted", "Artifacts and trained models are now active.")
        with RUN_LOCK:
            rebuild_job = mushroom_worker_jobs.finish_candidate_promotion(
                mushroom_worker_jobs_path(),
                job_id=rebuild_job_id,
                promoted=True,
                result=rebuild_promotion,
            )
            training_job = mushroom_worker_jobs.finish_candidate_promotion(
                mushroom_worker_jobs_path(),
                job_id=training_job_id,
                promoted=True,
                result={
                    **training_promotion,
                    "operational_install": operational_install,
                    "released_predictor_instances": released,
                    "predictor_runtime_publication": runtime_publication,
                },
            )
        mushroom_ml_multiversion_transport.discard_staged_result(
            mushroom_worker_candidate_results_path(), job_id=operational_job_id
        )
        discard_mushroom_worker_input_bundle(rebuild_job)
        discard_mushroom_worker_input_bundle(training_job)
        rebuild_cleanup = discard_promoted_mushroom_worker_result(rebuild_job)
        training_cleanup = discard_promoted_mushroom_worker_result(training_job)
        reconcile_mushroom_worker_storage_for_launch()
        warnings = " ".join(value for value in (rebuild_cleanup, training_cleanup) if value)
        set_mushroom_workers_flash(
            "Complete artifacts and their trained models were promoted as one generation."
            + (f" {warnings}" if warnings else "")
        )
    except Exception as exc:
        if installed_batch_id and not generation_promoted:
            mushroom_ml_multiversion_transport.remove_installed_batch(
                models_root=models_root,
                batch_id=installed_batch_id,
            )
            mushroom_ml_version_registry.save_registry(
                registry_path, json.loads(previous_registry)
            )
            mushroom_ml_training_freshness.restore_current_revisions(
                revisions_path, previous_revisions
            )
        for job_id in (rebuild_job_id, training_job_id):
            try:
                with RUN_LOCK:
                    mushroom_worker_jobs.finish_candidate_promotion(
                        mushroom_worker_jobs_path(),
                        job_id=job_id,
                        promoted=False,
                        error=str(exc),
                    )
            except ValueError:
                pass
        set_mushroom_workers_flash(str(exc), error=True)
    finally:
        with RUN_LOCK:
            MUSHROOM_WORKER_PROMOTION_THREADS.pop(training_job_id, None)


def promote_mushroom_full_update(training_job_id: str) -> tuple[int, dict[str, object]]:
    if not mushroom_worker_operational_enabled():
        return 404, {"ok": False, "error": "External worker promotion is not enabled."}
    try:
        with RUN_LOCK:
            training_job = mushroom_worker_jobs.get_job(
                mushroom_worker_jobs_path(), job_id=training_job_id
            )
            rebuild_job_id = str(training_job.get("triggered_by_job_id", "") or "")
            if training_job.get("job_type") != mushroom_worker_jobs.JOB_TYPE_ML_TRAIN or not rebuild_job_id:
                raise ValueError("Training job is not linked to a complete reconstruction.")
            rebuild_job = mushroom_worker_jobs.get_job(
                mushroom_worker_jobs_path(), job_id=rebuild_job_id
            )
            if not rebuild_job.get("full_update"):
                raise ValueError("Reconstruction job is not a complete update.")
            queue = mushroom_worker_jobs.load_queue(mushroom_worker_jobs_path())
            operational_job = next(
                (
                    row
                    for row in queue["jobs"]
                    if row.get("job_type") == mushroom_worker_jobs.JOB_TYPE_ML_MULTIVERSION
                    and row.get("job_purpose") == "operational"
                    and str(row.get("triggered_by_job_id", "")) == training_job_id
                ),
                None,
            )
            if not isinstance(operational_job, dict) or operational_job.get("status") != "complete":
                raise ValueError(
                    "The linked active-generation training must complete before the full generation can be promoted."
                )
            rebuild_job, training_job = mushroom_worker_jobs.begin_full_update_promotion(
                mushroom_worker_jobs_path(),
                rebuild_job_id=rebuild_job_id,
                training_job_id=training_job_id,
            )
            promotion_thread = threading.Thread(
                target=_run_mushroom_full_update_promotion,
                args=(rebuild_job_id, training_job_id, str(operational_job["job_id"])),
                daemon=True,
                name=f"rainmapper-full-update-promotion-{training_job_id[-12:]}",
            )
            MUSHROOM_WORKER_PROMOTION_THREADS[training_job_id] = promotion_thread
            promotion_thread.start()
    except (FileNotFoundError, ValueError, json.JSONDecodeError) as exc:
        return 409, {"ok": False, "error": str(exc)}
    set_mushroom_workers_flash("Promoting the complete verified generation.", clear_when_idle=True)
    return 202, {
        "ok": True,
        "job": training_job,
        "operational_job_id": operational_job.get("job_id", ""),
        "promoting": True,
    }


def resolve_mushroom_worker_input_download(
    *,
    job_id: str,
    logical_path: str,
    worker_id: str,
    claim_token: str,
    auth_token: str,
) -> tuple[int, Path | dict[str, object]]:
    if not mushroom_worker_api_enabled():
        return 404, {"ok": False, "error": "Worker API is not enabled."}
    if not authenticate_mushroom_worker(worker_id, auth_token):
        return 401, {"ok": False, "error": "Worker authentication failed."}
    try:
        with RUN_LOCK:
            job = mushroom_worker_jobs.authorize_input_download(
                mushroom_worker_jobs_path(),
                job_id=job_id,
                worker_id=worker_id,
                claim_token=claim_token,
            )
        if job.get("job_type") == mushroom_worker_jobs.JOB_TYPE_ML_TRAIN:
            safe_path = mushroom_worker_transport.safe_relative_path(logical_path)
            if safe_path.as_posix() not in {"job_spec.json", "features.json", "known_sites.json"}:
                raise ValueError("Requested ML training input path is not allowed.")
            bundle_path = mushroom_worker_input_bundles_path() / job_id / safe_path
            if not bundle_path.is_file():
                raise FileNotFoundError("ML training input file not found.")
            return 200, bundle_path
        if job.get("job_type") == mushroom_worker_jobs.JOB_TYPE_ML_MULTIVERSION:
            bundle = job.get("input_bundle")
            if not isinstance(bundle, dict) or not bundle.get("snapshot_id"):
                safe_path = mushroom_worker_transport.safe_relative_path(logical_path)
                declared = {
                    str(row.get("path", ""))
                    for row in (bundle.get("files", []) if isinstance(bundle, dict) else [])
                    if isinstance(row, dict)
                }
                if safe_path.as_posix() not in declared:
                    raise ValueError("Requested multiversion input path is not allowed.")
                bundle_path = mushroom_worker_input_bundles_path() / job_id / safe_path
                if not bundle_path.is_file():
                    raise FileNotFoundError("Multiversion input file not found.")
                return 200, bundle_path
        metadata = mushroom_worker_transport.load_coordinator_bundle(
            mushroom_worker_input_bundles_path(),
            job_id,
        )
        input_bundle = job.get("input_bundle")
        if not isinstance(input_bundle, dict):
            raise ValueError("Worker job input bundle contract is missing.")
        for key in (
            "job_spec_id",
            "snapshot_id",
            "input_file_count",
            "input_size_bytes",
            "dataset_id",
            "dataset_fingerprint",
            "dataset_file_count",
            "dataset_size_bytes",
        ):
            if key not in input_bundle:
                continue
            if metadata.get(key) != input_bundle.get(key):
                raise ValueError("Worker job input bundle no longer matches its immutable files.")
        path = mushroom_worker_transport.resolve_coordinator_file(
            mushroom_worker_input_bundles_path(),
            job_id,
            logical_path,
        )
    except (FileNotFoundError, ValueError, json.JSONDecodeError) as exc:
        return 409, {"ok": False, "error": str(exc)}
    return 200, path


def resolve_mushroom_worker_dataset_download(
    *,
    job_id: str,
    dataset_id: str,
    fingerprint: str,
    logical_path: str,
    worker_id: str,
    claim_token: str,
    auth_token: str,
) -> tuple[int, Path | dict[str, object]]:
    if not mushroom_worker_api_enabled():
        return 404, {"ok": False, "error": "Worker API is not enabled."}
    if not authenticate_mushroom_worker(worker_id, auth_token):
        return 401, {"ok": False, "error": "Worker authentication failed."}
    try:
        with RUN_LOCK:
            job = mushroom_worker_jobs.authorize_input_download(
                mushroom_worker_jobs_path(),
                job_id=job_id,
                worker_id=worker_id,
                claim_token=claim_token,
            )
        metadata = mushroom_worker_transport.load_coordinator_bundle(
            mushroom_worker_input_bundles_path(),
            job_id,
        )
        input_bundle = job.get("input_bundle")
        if not isinstance(input_bundle, dict):
            raise ValueError("Worker job input bundle contract is missing.")
        for key in ("dataset_id", "dataset_fingerprint", "dataset_file_count", "dataset_size_bytes"):
            if key in input_bundle and metadata.get(key) != input_bundle.get(key):
                raise ValueError("Worker job dataset no longer matches its immutable manifest.")
        if dataset_id != metadata.get("dataset_id") or fingerprint != metadata.get("dataset_fingerprint"):
            raise ValueError("Requested worker dataset does not match the assigned job.")
        path = mushroom_worker_transport.resolve_coordinator_dataset_file(
            mushroom_worker_input_bundles_path(),
            mushroom_gis_lab.gis_root(),
            job_id=job_id,
            dataset_id=dataset_id,
            fingerprint=fingerprint,
            logical_path=logical_path,
        )
    except (FileNotFoundError, RuntimeError, ValueError, json.JSONDecodeError) as exc:
        return 409, {"ok": False, "error": str(exc)}
    return 200, path


def cancel_mushroom_worker_job(job_id: str, *, force: bool = False) -> tuple[int, dict[str, object]]:
    try:
        with RUN_LOCK:
            job = mushroom_worker_jobs.request_cancel(
                mushroom_worker_jobs_path(),
                job_id=job_id,
                force=force,
            )
            if (
                job.get("job_type")
                == mushroom_worker_jobs.JOB_TYPE_PREDICTOR_PRECOMPUTE
            ):
                mushroom_predictor_precompute_control.cancel_desired_state(
                    mushroom_paths.mushroom_predictor_precompute_desired_path(),
                    desired_revision=int(job.get("desired_revision", 0) or 0),
                    artifact_id=str(job.get("artifact_id", "")),
                    cancelled_at=str(job.get("cancel_requested_at", "")),
                )
        discard_mushroom_worker_input_bundle(job)
        reconcile_mushroom_worker_storage_for_launch(
            str(job.get("target_worker_id", ""))
        )
    except ValueError as exc:
        return 409, {"ok": False, "error": str(exc)}
    return 200, {"ok": True, "job": job}


def cancel_remote_predictor_job(job_id: str) -> tuple[int, dict[str, object]]:
    """Request cooperative cancellation for one interactive Predictor job."""
    try:
        with RUN_LOCK:
            current = mushroom_worker_jobs.get_job(
                mushroom_worker_jobs_path(), job_id=job_id
            )
            if current.get("job_type") != mushroom_worker_jobs.JOB_TYPE_PREDICTOR:
                raise ValueError("Worker job is not an interactive Predictor request.")
            job = mushroom_worker_jobs.request_cancel(
                mushroom_worker_jobs_path(), job_id=job_id
            )
    except ValueError as exc:
        return 409, {"ok": False, "error": str(exc)}
    return 200, {
        "ok": True,
        "job_id": str(job.get("job_id", "")),
        "status": str(job.get("status", "")),
    }


def discard_mushroom_worker_candidate(job_id: str) -> tuple[int, dict[str, object]]:
    try:
        with RUN_LOCK:
            current_job = mushroom_worker_jobs.get_job(
                mushroom_worker_jobs_path(),
                job_id=job_id,
            )
            promotion_thread = MUSHROOM_WORKER_PROMOTION_THREADS.get(job_id)
            promotion_active = bool(promotion_thread and promotion_thread.is_alive())
            allow_interrupted_promotion = (
                str(current_job.get("promotion_status", "") or "") == "promoting"
                and not promotion_active
            )
            mushroom_worker_jobs.validate_candidate_discard(
                current_job,
                allow_interrupted_promotion=allow_interrupted_promotion,
            )
            mushroom_worker_results.discard_candidate(
                mushroom_worker_candidate_results_path(),
                mushroom_paths.mushroom_rebuild_artifacts_dir(),
                job_id=job_id,
            )
            mushroom_worker_transport.discard_coordinator_bundle(
                mushroom_worker_input_bundles_path(),
                job_id,
            )
            job = mushroom_worker_jobs.request_candidate_discard(
                mushroom_worker_jobs_path(),
                job_id=job_id,
                allow_interrupted_promotion=allow_interrupted_promotion,
            )
    except (FileNotFoundError, OSError, ValueError, json.JSONDecodeError) as exc:
        return 409, {"ok": False, "error": str(exc)}
    return 202, {"ok": True, "job": job, "discarding": True}


def reassign_mushroom_worker_job(job_id: str, worker_id: str) -> tuple[int, dict[str, object]]:
    target = next(
        (
            row
            for row in registered_mushroom_worker_statuses()
            if isinstance(row.get("payload"), dict)
            and str(row["payload"].get("worker_id", "")) == worker_id
        ),
        None,
    )
    if target is None:
        return 409, {"ok": False, "error": "The selected worker is not registered."}
    payload = target["payload"]
    try:
        with RUN_LOCK:
            current_job = mushroom_worker_jobs.get_job(
                mushroom_worker_jobs_path(),
                job_id=job_id,
            )
            input_bundle = current_job.get("input_bundle")
            input_bundle = input_bundle if isinstance(input_bundle, dict) else {}
            if (
                input_bundle.get("weather_transport") == "parquet"
                and not mushroom_worker_supports(
                    payload,
                    mushroom_worker_registry.WEATHER_PARQUET_CAPABILITY,
                )
            ):
                raise ValueError(
                    "The selected worker cannot read this Parquet input bundle."
                )
            job = mushroom_worker_jobs.reassign_job(
                mushroom_worker_jobs_path(),
                job_id=job_id,
                worker_id=worker_id,
                worker_display_name=str(payload.get("display_name", worker_id)),
            )
    except ValueError as exc:
        return 409, {"ok": False, "error": str(exc)}
    return 200, {"ok": True, "job": job}


def compact_duration(seconds: float | int | None) -> str:
    if seconds is None:
        return ""
    total = max(0, int(seconds))
    minutes, sec = divmod(total, 60)
    hours, minutes = divmod(minutes, 60)
    if hours:
        return f"{hours}h {minutes}m {sec}s"
    if minutes:
        return f"{minutes}m {sec}s"
    return f"{sec}s"


def parse_worker_job_datetime(value: object) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=UTC)
    return parsed


def format_worker_job_datetime(value: object) -> str:
    parsed = parse_worker_job_datetime(value)
    if parsed is None:
        return "-"
    return parsed.astimezone(get_timezone()).strftime("%d/%m/%Y %H:%M:%S")


def worker_job_elapsed(job: dict[str, object], *, now: datetime | None = None) -> str:
    return compact_duration(worker_job_elapsed_seconds(job, now=now))


def worker_job_elapsed_seconds(
    job: dict[str, object],
    *,
    now: datetime | None = None,
) -> float:
    started = parse_worker_job_datetime(job.get("created_at") or job.get("started_at"))
    if started is None:
        return 0
    finished = parse_worker_job_datetime(job.get("finished_at"))
    current = finished or now or datetime.now(UTC)
    if current.tzinfo is None:
        current = current.replace(tzinfo=UTC)
    return max(0, (current.astimezone(UTC) - started.astimezone(UTC)).total_seconds())


def worker_job_execution_elapsed_seconds(
    job: dict[str, object],
    *,
    now: datetime | None = None,
) -> float:
    started = parse_worker_job_datetime(job.get("started_at") or job.get("created_at"))
    if started is None:
        return 0
    finished = parse_worker_job_datetime(job.get("finished_at"))
    current = finished or now or datetime.now(UTC)
    if current.tzinfo is None:
        current = current.replace(tzinfo=UTC)
    return max(0, (current.astimezone(UTC) - started.astimezone(UTC)).total_seconds())


def worker_job_preparation_seconds(job: dict[str, object]) -> float:
    created = parse_worker_job_datetime(job.get("created_at"))
    started = parse_worker_job_datetime(job.get("started_at"))
    if created is None or started is None:
        return 0
    return max(0, (started.astimezone(UTC) - created.astimezone(UTC)).total_seconds())


def mushroom_workers_recent_jobs(
    *,
    limit: int = mushroom_worker_jobs.MAX_JOBS,
) -> list[dict[str, object]]:
    cleanup_mushroom_rebuild_jobs()
    with RUN_LOCK:
        rebuild_jobs = [mushroom_rebuild_job_payload(dict(job)) for job in MUSHROOM_REBUILD_JOBS.values()]
        external_jobs = mushroom_worker_jobs.recent_jobs(mushroom_worker_jobs_path(), limit=limit)
        promotion_active_by_job = {
            job_id: thread.is_alive()
            for job_id, thread in MUSHROOM_WORKER_PROMOTION_THREADS.items()
        }
    jobs: list[dict[str, object]] = []
    for job in rebuild_jobs:
        started_at = job.get("started_at", "")
        started = parse_worker_job_datetime(started_at)
        jobs.append(
            {
                **job,
                "created_at": started_at,
                "date_time": format_worker_job_datetime(started_at),
                "sort_timestamp": started.timestamp() if started is not None else 0,
                "opens_rebuild_modal": True,
            }
        )
    for job in external_jobs:
        public_job = {key: value for key, value in job.items() if key != "claim_token"}
        created_at = job.get("created_at", "")
        created = parse_worker_job_datetime(created_at)
        opens_rebuild_modal = job.get("job_type") in {
            mushroom_worker_jobs.JOB_TYPE_CANDIDATE_REBUILD,
            mushroom_worker_jobs.JOB_TYPE_ML_TRAIN,
            mushroom_worker_jobs.JOB_TYPE_ML_MULTIVERSION,
            mushroom_worker_jobs.JOB_TYPE_PREDICTOR_PRECOMPUTE,
        }
        jobs.append(
            {
                **public_job,
                "executor": "worker",
                "worker_display_name": job.get("target_display_name", ""),
                "date_time": format_worker_job_datetime(created_at),
                "elapsed": worker_job_elapsed(job),
                "elapsed_seconds": worker_job_elapsed_seconds(job),
                "execution_elapsed_seconds": worker_job_execution_elapsed_seconds(job),
                "preparation_seconds": worker_job_preparation_seconds(job),
                "sort_timestamp": created.timestamp() if created is not None else 0,
                "opens_rebuild_modal": opens_rebuild_modal,
                "promotion_active": bool(
                    promotion_active_by_job.get(str(job.get("job_id", "")), False)
                ),
            }
        )
    return sorted(
        jobs,
        key=lambda job: float(job.get("sort_timestamp", 0) or 0),
        reverse=True,
    )[: limit + len(rebuild_jobs)]


def mushroom_worker_activity_active(
    jobs: list[dict[str, object]],
    *,
    include_precompute: bool = True,
) -> bool:
    if MUSHROOM_WORKER_BUNDLE_PREPARATION_LOCK.locked():
        return True
    return any(
        (
            include_precompute
            or str(job.get("job_type", ""))
            not in {
                mushroom_worker_jobs.JOB_TYPE_PREDICTOR_PRECOMPUTE,
                "local_predictor_precompute",
            }
        )
        and str(job.get("status", "")) in mushroom_worker_jobs.ACTIVE_STATUSES
        or (
            str(job.get("promotion_status", "")) == "promoting"
            and bool(job.get("promotion_active", True))
        )
        or str(job.get("discard_status", "")) == "requested"
        for job in jobs
    )


def mushroom_workers_status_refresh_payload() -> dict[str, object]:
    worker_statuses = registered_mushroom_worker_statuses()
    jobs = mushroom_workers_recent_jobs()
    operational_enabled = mushroom_worker_operational_enabled()
    default_executor = mushroom_worker_registry.load_registry(
        mushroom_worker_registry_path()
    )["default_executor"]
    worker_cards_html = mushroom_workers_ui.render_worker_cards(
        worker_statuses,
        default_executor=default_executor,
    )
    worker_choices_html = mushroom_workers_ui.render_worker_choices(
        worker_statuses,
        operational_enabled=operational_enabled,
        default_executor=default_executor,
        local_ha_compute_enabled=mushroom_local_ha_compute_enabled(),
    )
    recent_jobs_html = mushroom_workers_ui.render_recent_jobs(
        jobs,
        worker_statuses,
        operational_enabled=operational_enabled,
    )
    precompute_state_html = mushroom_workers_ui.render_precompute_state(
        predictor_precompute_summary()
    )
    activity_active = mushroom_worker_activity_active(jobs)
    flash, flash_error, flash_clear_when_idle = mushroom_workers_flash_details()
    if flash_clear_when_idle and not activity_active:
        flash = ""
        flash_error = False
        flash_clear_when_idle = False
    worker_last_checks = {}
    for worker_status in worker_statuses:
        payload = worker_status.get("payload")
        if not isinstance(payload, dict):
            continue
        worker_id = str(payload.get("worker_id", ""))
        if worker_id:
            worker_last_checks[worker_id] = mushroom_workers_ui.format_worker_checked_at(
                worker_status.get("checked_at", "-")
            )
    return {
        "ok": True,
        "stale_after_seconds": MUSHROOM_WORKER_STALE_SECONDS,
        "worker_cards_html": worker_cards_html,
        "worker_cards_signature": mushroom_workers_ui.worker_cards_refresh_signature(
            worker_statuses,
            default_executor=default_executor,
        ),
        "worker_choices_html": worker_choices_html,
        "worker_choices_signature": mushroom_workers_ui.refresh_signature(worker_choices_html),
        "recent_jobs_html": recent_jobs_html,
        "recent_jobs_signature": mushroom_workers_ui.refresh_signature(recent_jobs_html),
        "precompute_state_html": precompute_state_html,
        "precompute_state_signature": mushroom_workers_ui.refresh_signature(
            precompute_state_html
        ),
        "worker_last_checks": worker_last_checks,
        "worker_activity_active": activity_active,
        "flash_update": bool(flash),
        "flash_html": mushroom_workers_ui.render_worker_flash(
            flash,
            error=flash_error,
        ),
        "flash_clear_when_idle": flash_clear_when_idle,
    }


def append_query_param(url: str, key: str, value: str) -> str:
    base, sep, anchor = url.partition("#")
    delimiter = "&" if "?" in base else "?"
    updated = f"{base}{delimiter}{urlencode({key: value})}"
    return f"{updated}{sep}{anchor}" if sep else updated


def observation_species_ids(rows: list[dict[str, object]]) -> list[str]:
    return sorted({str(row.get("species_id", "") or "").strip() for row in rows if str(row.get("species_id", "") or "").strip()})


def observation_has_coordinates(row: dict[str, object]) -> bool:
    location = row.get("location")
    if not isinstance(location, dict):
        return False
    try:
        float(location.get("lat"))  # type: ignore[arg-type]
        float(location.get("lon"))  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return False
    return True


def eligible_model_species_ids(observations: list[dict[str, object]]) -> list[str]:
    return observation_species_ids(
        [
            row
            for row in observations
            if str(row.get("validation_status", "") or "").strip() == "valid"
            and str(row.get("calibration_use", "") or "").strip() == "include"
            and observation_has_coordinates(row)
        ]
    )


def pending_model_species_ids(
    state: dict[str, object],
    observations: list[dict[str, object]],
    *,
    learned_model_payload: object = None,
) -> list[str]:
    eligible_species = set(eligible_model_species_ids(observations))
    pending_species = [
        str(value).strip()
        for value in state.get("pending_rebuild_species_ids", [])
        if str(value or "").strip()
    ]
    pending_species = sorted({species_id for species_id in pending_species if species_id in eligible_species})
    if pending_species:
        return pending_species
    if learned_model_payload is None:
        return sorted(eligible_species)
    return []


def eligible_observation_ids_for_species(
    observations: list[dict[str, object]],
    species_ids: list[str] | set[str],
) -> list[str]:
    selected_species = {str(species_id).strip() for species_id in species_ids if str(species_id or "").strip()}
    ids = []
    for row in observations:
        if str(row.get("species_id", "") or "").strip() not in selected_species:
            continue
        if str(row.get("validation_status", "") or "").strip() != "valid":
            continue
        if str(row.get("calibration_use", "") or "").strip() != "include":
            continue
        if not observation_has_coordinates(row):
            continue
        observation_id = str(row.get("observation_id", "") or "").strip()
        if observation_id:
            ids.append(observation_id)
    return ids


def cleanup_mushroom_rebuild_jobs(now: float | None = None) -> None:
    now = now if now is not None else time.time()
    with RUN_LOCK:
        expired = [
            job_id
            for job_id, job in MUSHROOM_REBUILD_JOBS.items()
            if job.get("finished_at_ts") and now - float(job.get("finished_at_ts") or 0) > MUSHROOM_REBUILD_JOB_TTL_SECONDS
        ]
        for job_id in expired:
            MUSHROOM_REBUILD_JOBS.pop(job_id, None)


def mushroom_rebuild_job_payload(job: dict[str, object]) -> dict[str, object]:
    now = time.time()
    started_at_ts = float(job.get("started_at_ts") or now)
    phase_started_at_ts = float(job.get("phase_started_at_ts") or started_at_ts)
    finished_at_ts = job.get("finished_at_ts")
    current_ts = float(finished_at_ts or now)
    total_elapsed = current_ts - started_at_ts
    phase_elapsed = current_ts - phase_started_at_ts
    overall_percent = int(job.get("overall_percent") or 0)
    phase_percent = int(job.get("phase_percent") or 0)

    total_eta = None
    if 0 < overall_percent < 100:
        total_eta = max(0, (total_elapsed / overall_percent) * (100 - overall_percent))
    phase_eta = None
    if 0 < phase_percent < 100:
        phase_eta = max(0, (phase_elapsed / phase_percent) * (100 - phase_percent))

    payload: dict[str, object] = {
        "job_id": job.get("job_id", ""),
        "job_type": job.get("job_type", "rebuild_v0"),
        "job_purpose": job.get("job_purpose", ""),
        "profile_keys": list(job.get("profile_keys") or []),
        "profile_labels": list(job.get("profile_labels") or []),
        "executor": "home_assistant",
        "worker_display_name": job.get("worker_display_name", "Home Assistant"),
        "status": job.get("status", "unknown"),
        "phase": job.get("phase", ""),
        "phase_index": job.get("phase_index", 0),
        "phase_count": job.get("phase_count", 0),
        "phase_percent": phase_percent,
        "overall_percent": overall_percent,
        "message": job.get("message", ""),
        "error": job.get("error", ""),
        "result": job.get("result", {}),
        "scope": job.get("scope", ""),
        "pipeline": job.get("pipeline", "legacy"),
        "cancel_requested": bool(job.get("cancel_requested", False)),
        "can_cancel": (
            job.get("pipeline") in {"shared", "local_benchmark"}
            and job.get("status") == "running"
            and not bool(job.get("_promotion_started", False))
        ),
        "elapsed": compact_duration(total_elapsed),
        "elapsed_seconds": max(0, total_elapsed),
        "phase_elapsed": compact_duration(phase_elapsed),
        "eta": compact_duration(total_eta) if total_eta is not None else "",
        "phase_eta": compact_duration(phase_eta) if phase_eta is not None else "",
        "started_at": job.get("started_at", ""),
        "finished_at": job.get("finished_at", ""),
    }
    if job.get("job_type") == "local_predictor_precompute":
        progress_detail = predictor_precompute_progress_detail(
            job,
            phase_index=int(job.get("phase_index") or 0),
            phase_percent=phase_percent,
            phase_count=int(job.get("phase_count") or 2),
        )
        payload.update(
            {
                "title": mushroom_profiles_ui.ui_label(
                    "ui.worker_predictor_precompute_job_type"
                ),
                "message": progress_detail["stage_message"],
                **progress_detail,
            }
        )
    return payload


def set_mushroom_rebuild_progress(
    job_id: str,
    *,
    status: str | None = None,
    phase: str | None = None,
    phase_index: int | None = None,
    phase_count: int | None = None,
    phase_percent: int | None = None,
    overall_percent: int | None = None,
    message: str | None = None,
    error: str | None = None,
    result: dict[str, object] | None = None,
    reset_phase_timer: bool = False,
) -> None:
    now = time.time()
    with RUN_LOCK:
        job = MUSHROOM_REBUILD_JOBS.get(job_id)
        if not job:
            return
        if status is not None:
            job["status"] = status
        if phase is not None:
            job["phase"] = phase
        if phase_index is not None:
            job["phase_index"] = phase_index
        if phase_count is not None:
            job["phase_count"] = phase_count
        if phase_percent is not None:
            job["phase_percent"] = max(0, min(100, int(phase_percent)))
        if overall_percent is not None:
            job["overall_percent"] = max(0, min(100, int(overall_percent)))
        if message is not None:
            job["message"] = message
        if error is not None:
            job["error"] = error
        if result is not None:
            job["result"] = result
        if reset_phase_timer:
            job["phase_started_at_ts"] = now
        if status in {"complete", "failed", "cancelled"}:
            job["finished_at_ts"] = now
            job["finished_at"] = datetime.now(get_timezone()).isoformat(timespec="seconds")


_PRECOMPUTE_PROGRESS_RE = re.compile(
    r"^(?P<done>\d+(?:\.\d+)?)/(?P<total>\d+):\s*(?P<detail>.*)$"
)


def predictor_precompute_progress_detail(
    external: dict[str, object],
    *,
    phase_index: int,
    phase_percent: int,
    phase_count: int = 3,
) -> dict[str, object]:
    """Project worker telemetry into a stable, user-facing progress hierarchy."""
    label = mushroom_profiles_ui.ui_label
    status = str(external.get("status", "") or "")
    raw_phase = str(external.get("phase", "") or "")
    raw_message = str(external.get("message", "") or "")
    stage_labels = {
        1: label("ui.precompute_progress_stage_calculation"),
        2: label("ui.precompute_progress_stage_ha"),
        3: label("ui.precompute_progress_stage_worker"),
    }
    stage_messages = {
        1: label("ui.precompute_progress_stage_calculation_help"),
        2: label("ui.precompute_progress_stage_ha_help"),
        3: label("ui.precompute_progress_stage_worker_help"),
    }
    if phase_count == 2:
        stage_labels[2] = label("ui.precompute_progress_stage_local")
        stage_messages[2] = label("ui.precompute_progress_stage_local_help")
    if status == "complete":
        stage_message = label("ui.precompute_progress_complete")
    elif status in {"failed", "cancelled"}:
        stage_message = raw_message
    else:
        stage_message = stage_messages.get(phase_index, raw_message)

    detail: dict[str, object] = {
        "progress_kind": "predictor_precompute",
        "stage_name": stage_labels.get(phase_index, raw_phase),
        "stage_message": stage_message,
        "stage_percent": phase_percent,
        "stage_indeterminate": (
            status not in mushroom_worker_jobs.TERMINAL_STATUSES
            and phase_index in set(range(2, phase_count + 1))
        ),
        "technical_phase": raw_phase,
        "technical_message": raw_message,
        "scientific_done": "",
        "scientific_total": 0,
        "scientific_percent": None,
        "scientific_substep": "",
        "trace_view": "",
        "trace_species": "",
        "trace_area": "",
    }
    match = _PRECOMPUTE_PROGRESS_RE.match(raw_message)
    if phase_index != 1 or match is None:
        return detail

    done_text = match.group("done")
    total = int(match.group("total"))
    raw_detail = match.group("detail").strip()
    scope, separator, technical_step = raw_detail.partition(" · ")
    scope_parts = scope.split(":")
    view = scope_parts[0] if scope_parts else ""
    species = scope_parts[1] if len(scope_parts) > 1 else ""
    area = scope_parts[2] if len(scope_parts) > 2 else ""
    phase_text = technical_step.partition(":")[0].strip() if separator else ""
    if raw_detail == "Finalizing and validating SQLite artifact":
        substep = label("ui.precompute_progress_substep_finalizing")
    elif phase_text == "Building weekly matrix":
        substep = label("ui.precompute_progress_substep_matrix")
    else:
        substep = label("ui.precompute_progress_substep_scientific")
    view_labels = {
        "recommender": label("ui.predictor_tab_recommender"),
        "week": label("ui.predictor_tab_week"),
        "query": label("ui.predictor_tab_query"),
    }
    done = float(done_text)
    detail.update(
        {
            "scientific_done": done_text,
            "scientific_total": total,
            "scientific_percent": round(done * 100 / max(1, total), 1),
            "stage_percent": round(done * 100 / max(1, total), 1),
            "scientific_substep": substep,
            "trace_view": view_labels.get(view, view),
            "trace_species": species.replace("_", " ").capitalize(),
            "trace_area": area.replace("_", " ").capitalize(),
        }
    )
    return detail


def get_mushroom_rebuild_job_status(job_id: str) -> dict[str, object] | None:
    cleanup_mushroom_rebuild_jobs()
    with RUN_LOCK:
        job = MUSHROOM_REBUILD_JOBS.get(job_id)
        if job:
            return mushroom_rebuild_job_payload(dict(job))
        try:
            external = mushroom_worker_jobs.get_job(
                mushroom_worker_jobs_path(), job_id=job_id
            )
        except (FileNotFoundError, ValueError):
            return None
    job_type = str(external.get("job_type", "") or "")
    overall_percent = max(0, min(100, int(external.get("overall_percent", 0) or 0)))
    phase = str(external.get("phase", "") or "")
    elapsed_seconds = worker_job_elapsed_seconds(external)
    eta_seconds = (
        max(0.0, elapsed_seconds / overall_percent * (100 - overall_percent))
        if 0 < overall_percent < 100
        else None
    )
    if job_type != mushroom_worker_jobs.JOB_TYPE_PREDICTOR_PRECOMPUTE:
        title_key = {
            mushroom_worker_jobs.JOB_TYPE_CANDIDATE_REBUILD: (
                "ui.worker_candidate_rebuild"
            ),
            mushroom_worker_jobs.JOB_TYPE_ML_TRAIN: "ui.worker_ml_train_job_type",
            mushroom_worker_jobs.JOB_TYPE_ML_MULTIVERSION: (
                "ui.worker_operational_training_job"
                if external.get("job_purpose") == "operational"
                else "ui.worker_scientific_benchmark_job"
            ),
        }.get(job_type)
        if title_key is None:
            return None
        return {
            "job_id": external.get("job_id", ""),
            "job_type": job_type,
            "title": mushroom_profiles_ui.ui_label(title_key),
            "executor": "worker",
            "worker_display_name": external.get("target_display_name", ""),
            "status": external.get("status", "unknown"),
            "phase": phase,
            "phase_index": 1,
            "phase_count": 1,
            "phase_percent": overall_percent,
            "overall_percent": overall_percent,
            "message": external.get("message", ""),
            "error": external.get("error", ""),
            "result": external.get("result", {}),
            "scope": external.get("scope", ""),
            "pipeline": "worker_job",
            "cancel_requested": external.get("status") == "cancel_requested",
            "can_cancel": False,
            "elapsed": worker_job_elapsed(external),
            "elapsed_seconds": elapsed_seconds,
            "phase_elapsed": worker_job_elapsed(external),
            "eta": compact_duration(eta_seconds) if eta_seconds is not None else "",
            "phase_eta": compact_duration(eta_seconds) if eta_seconds is not None else "",
            "started_at": external.get("started_at") or external.get("created_at", ""),
            "finished_at": external.get("finished_at", ""),
        }
    if overall_percent >= 100 or external.get("status") == "complete":
        phase_index, phase_percent = 3, 100
    elif phase == "Activating verified worker copy":
        phase_index, phase_percent = 3, 0
    elif phase == "Uploading verified SQLite":
        phase_index, phase_percent = 2, 0
    else:
        phase_index = 1
        phase_percent = max(0, min(100, int((overall_percent - 10) * 100 / 65)))
    progress_detail = predictor_precompute_progress_detail(
        external,
        phase_index=phase_index,
        phase_percent=phase_percent,
    )
    return {
        "job_id": external.get("job_id", ""),
        "job_type": external.get("job_type", ""),
        "title": mushroom_profiles_ui.ui_label("ui.worker_predictor_precompute_job_type"),
        "executor": "worker",
        "worker_display_name": external.get("target_display_name", ""),
        "status": external.get("status", "unknown"),
        "phase": phase,
        "phase_index": phase_index,
        "phase_count": 3,
        "phase_percent": phase_percent,
        "overall_percent": overall_percent,
        "message": progress_detail["stage_message"],
        "error": external.get("error", ""),
        "result": external.get("result", {}),
        "scope": external.get("scope", ""),
        "pipeline": "worker_predictor_precompute",
        "cancel_requested": external.get("status") == "cancel_requested",
        "can_cancel": False,
        "elapsed": worker_job_elapsed(external),
        "elapsed_seconds": elapsed_seconds,
        "phase_elapsed": worker_job_elapsed(external),
        "eta": compact_duration(eta_seconds) if eta_seconds is not None else "",
        "phase_eta": "",
        "started_at": external.get("started_at", ""),
        "finished_at": external.get("finished_at", ""),
        **progress_detail,
    }


def request_mushroom_rebuild_cancel(job_id: str) -> tuple[int, dict[str, object]]:
    with RUN_LOCK:
        job = MUSHROOM_REBUILD_JOBS.get(job_id)
        if not job:
            return 404, {"ok": False, "error": "Rebuild job was not found."}
        if job.get("pipeline") not in {
            "shared",
            "local_benchmark",
            "local_predictor_precompute",
        }:
            return 409, {"ok": False, "error": "Legacy rebuild jobs cannot be cancelled safely."}
        if job.get("status") != "running":
            return 409, {"ok": False, "error": "Rebuild job is no longer running."}
        if job.get("_promotion_started"):
            return 409, {"ok": False, "error": "Rebuild results are already being promoted."}
        cancel_event = job.get("_cancel_event")
        if not isinstance(cancel_event, threading.Event):
            return 500, {"ok": False, "error": "Rebuild cancellation event is unavailable."}
        cancel_event.set()
        job["cancel_requested"] = True
        job["message"] = "Cancellation requested. Waiting for a safe stopping point."
        return 202, {"ok": True, "job": mushroom_rebuild_job_payload(dict(job))}


def render_mushroom_profiles_flash(message: str) -> str:
    text = str(message or "").strip()
    if not text:
        return ""
    lowered = text.lower()
    is_error = (
        "not saved" in lowered
        or "invalid json" in lowered
        or "failed" in lowered
        or "was not found" in lowered
        or "unknown species" in lowered
    )
    if not is_error:
        return f'<div id="mushroom-profile-message" class="catalog-alert"><strong>Status</strong><br>{html.escape(text)}</div>'
    return (
        '<div id="mushroom-profile-message" class="catalog-alert error">'
        f"<strong>Validation error</strong><br>{html.escape(text)}"
        "<br><span class=\"meta\">Nothing was saved. Review the fields and save again.</span>"
        "</div>"
    )


